// Normalise the incoming form payload and validate it.
// Runs once for all items; each webhook call is a single item.
const FREE_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'hotmail.com', 'outlook.com', 'live.com',
  'yahoo.com', 'ymail.com', 'icloud.com', 'me.com', 'aol.com', 'proton.me',
  'protonmail.com', 'gmx.com', 'mail.com', 'msn.com'
]);
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const trim = (v) => (typeof v === 'string' ? v.trim() : v ?? '');

return $input.all().map((item) => {
  const body = item.json.body || {};
  const errors = [];

  const rawName = trim(body.name);
  const email = trim(body.email).toLowerCase();
  const company = trim(body.company);
  const message = trim(body.message);
  const source = trim(body.source) || 'website';

  if (!rawName) errors.push('name is required');
  if (!email) errors.push('email is required');
  else if (!EMAIL_RE.test(email)) errors.push('email format is invalid');
  if (message.length > 5000) errors.push('message is too long (max 5000 chars)');

  const parts = rawName.split(/\s+/).filter(Boolean);
  const firstName = parts[0] || '';
  const lastName = parts.slice(1).join(' ');
  const domain = email.includes('@') ? email.split('@')[1] : '';

  return {
    json: {
      valid: errors.length === 0,
      errors,
      firstName,
      lastName,
      fullName: rawName,
      email,
      domain,
      isFreeDomain: FREE_DOMAINS.has(domain),
      company,
      message,
      source,
      receivedAt: new Date().toISOString(),
    },
  };
});

// Combine the normalised lead with whatever the enrichment API returned.
// This node receives items from BOTH outputs of "Enrich Lead":
//  - success output: $json is the API response
//  - error output:   $json carries an `error` property (API failed after retries)
const lead = $('Normalise & Validate').item.json;
const api = $json || {};
const enrichmentFailed = Boolean(api.error) || Object.keys(api).length === 0;

// Adapt these paths to your enrichment vendor's response shape.
const enrichment = enrichmentFailed
  ? { status: 'unavailable', companyName: '', companySize: null, industry: '', linkedin: '' }
  : {
      status: 'ok',
      companyName: api.company?.name || '',
      companySize: api.company?.employees ?? null,
      industry: api.company?.industry || '',
      linkedin: api.person?.linkedin || '',
    };

const BUSINESS_SIZE_THRESHOLD = 10;
const isBusiness =
  !lead.isFreeDomain ||
  (typeof enrichment.companySize === 'number' && enrichment.companySize >= BUSINESS_SIZE_THRESHOLD);

return {
  json: {
    ...lead,
    enrichment,
    isBusiness,
    route: isBusiness ? 'crm' : 'low-priority-sheet',
    companyName: lead.company || enrichment.companyName || lead.domain,
  },
};

